CREATE TABLE "RehearsalEnvironment" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"stableId" VARCHAR(160) NOT NULL,"name" VARCHAR(200) NOT NULL,"environment" VARCHAR(40) NOT NULL,"status" VARCHAR(32) NOT NULL,"isolationProof" JSONB NOT NULL,"dataPolicy" JSONB NOT NULL,"providerPolicy" JSONB NOT NULL,"notificationPolicy" JSONB NOT NULL,"configurationVersion" VARCHAR(160) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RehearsalEnvironment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DigitalTwin" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"stableId" VARCHAR(160) NOT NULL,"environmentId" UUID NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"applicationVersion" VARCHAR(160) NOT NULL,"schemaVersion" VARCHAR(160) NOT NULL,"configurationVersion" VARCHAR(160) NOT NULL,"featureFlagVersion" VARCHAR(160) NOT NULL,"seedVersion" VARCHAR(160) NOT NULL,"dataGenerationVersion" VARCHAR(160) NOT NULL,"state" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DigitalTwin_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinComponent" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"twinId" UUID NOT NULL,"stableId" VARCHAR(160) NOT NULL,"domain" VARCHAR(80) NOT NULL,"componentType" VARCHAR(80) NOT NULL,"contract" JSONB NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinComponent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinDependency" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"twinId" UUID NOT NULL,"stableId" VARCHAR(160) NOT NULL,"dependencyType" VARCHAR(40) NOT NULL,"contract" JSONB NOT NULL,"availability" JSONB NOT NULL,"testMode" VARCHAR(40) NOT NULL,"failureSimulation" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinDependency_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinState" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"twinId" UUID NOT NULL,"stateKey" VARCHAR(160) NOT NULL,"value" JSONB NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinState_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinSnapshot" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"twinId" UUID NOT NULL,"snapshotKey" VARCHAR(160) NOT NULL,"sourceEnvironment" VARCHAR(40) NOT NULL,"creationTimestamp" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"schemaVersion" VARCHAR(160) NOT NULL,"applicationVersion" VARCHAR(160) NOT NULL,"configurationVersion" VARCHAR(160) NOT NULL,"featureFlagVersion" VARCHAR(160) NOT NULL,"seedVersion" VARCHAR(160) NOT NULL,"dataGenerationVersion" VARCHAR(160) NOT NULL,"dataClassification" VARCHAR(80) NOT NULL,"state" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinSnapshot_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinScenario" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"stableId" VARCHAR(160) NOT NULL,"name" VARCHAR(200) NOT NULL,"category" VARCHAR(80) NOT NULL,"lifecycleState" VARCHAR(32) NOT NULL,"owner" VARCHAR(160) NOT NULL,"riskClass" VARCHAR(32) NOT NULL,"maxDurationSeconds" INTEGER NOT NULL,"maxResourceUnits" INTEGER NOT NULL,"customerImpact" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinScenario_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinScenarioVersion" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"scenarioId" UUID NOT NULL,"version" INTEGER NOT NULL,"applicationVersion" VARCHAR(160) NOT NULL,"configurationVersion" VARCHAR(160) NOT NULL,"schemaVersion" VARCHAR(160) NOT NULL,"featureFlagVersion" VARCHAR(160) NOT NULL,"dataSeed" VARCHAR(160) NOT NULL,"faultDefinitions" JSONB NOT NULL,"steps" JSONB NOT NULL,"assertions" JSONB NOT NULL,"expected" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinScenarioVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinExecution" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"scenarioId" UUID NOT NULL,"scenarioVersion" INTEGER NOT NULL,"environmentId" UUID NOT NULL,"twinId" UUID NOT NULL,"state" VARCHAR(32) NOT NULL,"outcome" VARCHAR(32) NOT NULL,"requestedBy" VARCHAR(160) NOT NULL,"correlationId" VARCHAR(128),"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endedAt" TIMESTAMP(3),"expected" JSONB NOT NULL,"actual" JSONB,"recovery" JSONB,"customerImpact" JSONB NOT NULL,"cleanup" JSONB,"cost" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinExecution_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinStep" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"executionId" UUID NOT NULL,"stepNumber" INTEGER NOT NULL,"action" VARCHAR(160) NOT NULL,"state" VARCHAR(32) NOT NULL,"input" JSONB NOT NULL,"output" JSONB,"errorCode" TEXT,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endedAt" TIMESTAMP(3),CONSTRAINT "TwinStep_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinObservation" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"executionId" UUID NOT NULL,"metricKey" VARCHAR(160) NOT NULL,"observedValue" JSONB NOT NULL,"status" VARCHAR(32) NOT NULL,"evidence" JSONB NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinObservation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinFault" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"scenarioVersionId" UUID NOT NULL,"stableId" VARCHAR(160) NOT NULL,"faultType" VARCHAR(80) NOT NULL,"target" VARCHAR(160) NOT NULL,"parameters" JSONB NOT NULL,"simulationOnly" BOOLEAN NOT NULL DEFAULT true,"enabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinFault_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinAssertion" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"scenarioVersionId" UUID NOT NULL,"assertionKey" VARCHAR(160) NOT NULL,"assertionType" VARCHAR(80) NOT NULL,"expected" JSONB NOT NULL,"actual" JSONB,"status" VARCHAR(32) NOT NULL,"evidence" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinAssertion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinComparison" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"executionId" UUID NOT NULL,"dimension" VARCHAR(120) NOT NULL,"expected" JSONB NOT NULL,"actual" JSONB NOT NULL,"classification" VARCHAR(40) NOT NULL,"deviation" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinComparison_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinDrift" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"twinId" UUID NOT NULL,"dimension" VARCHAR(120) NOT NULL,"productionValue" JSONB NOT NULL,"rehearsalValue" JSONB NOT NULL,"classification" VARCHAR(40) NOT NULL,"blocksCertification" BOOLEAN NOT NULL DEFAULT false,"detectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinDrift_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinCertification" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"scenarioId" UUID NOT NULL,"scenarioVersion" INTEGER NOT NULL,"executionId" UUID,"status" VARCHAR(40) NOT NULL,"dimensions" JSONB NOT NULL,"testedScenarios" JSONB NOT NULL,"passedScenarios" JSONB NOT NULL,"failedScenarios" JSONB NOT NULL,"untestedScenarios" JSONB NOT NULL,"knownLimitations" JSONB NOT NULL,"residualRisks" JSONB NOT NULL,"certifiedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinCertification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TwinEvidence" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"executionId" UUID NOT NULL,"evidenceType" VARCHAR(80) NOT NULL,"reference" VARCHAR(1000) NOT NULL,"integrityHash" VARCHAR(128) NOT NULL,"payload" JSONB NOT NULL,"immutable" BOOLEAN NOT NULL DEFAULT true,"capturedBy" VARCHAR(160),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TwinEvidence_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "RehearsalEnvironment_stableId_idx" ON "RehearsalEnvironment"("stableId");
CREATE INDEX "RehearsalEnvironment_environment_status_idx" ON "RehearsalEnvironment"("environment","status");
CREATE UNIQUE INDEX "DigitalTwin_stableId_idx" ON "DigitalTwin"("stableId");
CREATE INDEX "DigitalTwin_environmentId_version_idx" ON "DigitalTwin"("environmentId","version");
CREATE UNIQUE INDEX "TwinComponent_twinId_stableId_idx" ON "TwinComponent"("twinId","stableId");
CREATE UNIQUE INDEX "TwinDependency_twinId_stableId_idx" ON "TwinDependency"("twinId","stableId");
CREATE UNIQUE INDEX "TwinState_twinId_stateKey_idx" ON "TwinState"("twinId","stateKey");
CREATE UNIQUE INDEX "TwinSnapshot_twinId_snapshotKey_idx" ON "TwinSnapshot"("twinId","snapshotKey");
CREATE UNIQUE INDEX "TwinScenario_stableId_idx" ON "TwinScenario"("stableId");
CREATE INDEX "TwinScenario_lifecycleState_updatedAt_idx" ON "TwinScenario"("lifecycleState","updatedAt");
CREATE UNIQUE INDEX "TwinScenarioVersion_scenarioId_version_idx" ON "TwinScenarioVersion"("scenarioId","version");
CREATE INDEX "TwinExecution_scenarioId_createdAt_idx" ON "TwinExecution"("scenarioId","createdAt");
CREATE INDEX "TwinExecution_state_createdAt_idx" ON "TwinExecution"("state","createdAt");
CREATE UNIQUE INDEX "TwinStep_executionId_stepNumber_idx" ON "TwinStep"("executionId","stepNumber");
CREATE INDEX "TwinObservation_executionId_observedAt_idx" ON "TwinObservation"("executionId","observedAt");
CREATE INDEX "TwinFault_scenarioVersionId_stableId_idx" ON "TwinFault"("scenarioVersionId","stableId");
CREATE INDEX "TwinAssertion_scenarioVersionId_assertionKey_idx" ON "TwinAssertion"("scenarioVersionId","assertionKey");
CREATE INDEX "TwinComparison_executionId_dimension_idx" ON "TwinComparison"("executionId","dimension");
CREATE INDEX "TwinDrift_twinId_classification_detectedAt_idx" ON "TwinDrift"("twinId","classification","detectedAt");
CREATE INDEX "TwinCertification_scenarioId_status_expiresAt_idx" ON "TwinCertification"("scenarioId","status","expiresAt");
CREATE INDEX "TwinEvidence_executionId_createdAt_idx" ON "TwinEvidence"("executionId","createdAt");

