INSERT INTO "RehearsalEnvironment" ("id","stableId","name","environment","status","isolationProof","dataPolicy","providerPolicy","notificationPolicy","configurationVersion") VALUES (gen_random_uuid(),'rehearsal-isolated','4HRS+ isolated rehearsal environment','rehearsal','READY','{"separateCredentials":true,"separateDatabase":true,"separateQueues":true,"separateCache":true,"separateSearch":true,"separateStorage":true,"separateProviderConfiguration":true,"separateNotificationDestinations":true,"productionWriteBlocked":true,"productionSecretsAbsent":true}','{"syntheticOnly":true,"piiAllowed":false,"credentialsAllowed":false,"paymentSecretsAllowed":false}','{"payment":"mocked","qikink":"mocked-safe-adapter","shipping":"simulated","unrestrictedNetwork":false,"realTransactions":false}','{"destination":"sink","realRecipients":false}','ci-default') ON CONFLICT ("stableId") DO NOTHING;